		public void Test_01_VerifySignature(Type HashFunction, Type Mgf1HashFunction, string Modulus,
			string Exponent, string Msg, string Signature, string SaltVal, bool Pass)
		{
			TravelDocuments.Security.HashFunctions.HashFunction H = (TravelDocuments.Security.HashFunctions.HashFunction)Types.Instantiate(HashFunction);
			MaskGenerationFunction Mgf = new MGF1((TravelDocuments.Security.HashFunctions.HashFunction)Types.Instantiate(Mgf1HashFunction));
			BigInteger n = EllipticCurve.ToInt(Hashes.StringToBinary(Modulus), true);
			BigInteger e = EllipticCurve.ToInt(Hashes.StringToBinary(Exponent), true);
			byte[] Message = Hashes.StringToBinary(Msg);
			BigInteger S = EllipticCurve.ToInt(Hashes.StringToBinary(Signature), true);
			byte[] Salt = Hashes.StringToBinary(SaltVal);

			if (Pass != RsaPss.Verify(H, Mgf, n, e, Message, S, Salt.Length))
			{
				Console.Out.WriteLine("H: " + HashFunction.Name);
				Console.Out.WriteLine("MGF1(H): " + Mgf1HashFunction.Name);
				Console.Out.WriteLine("Modulus: " + Modulus);
				Console.Out.WriteLine("Exponent: " + Exponent);
				Console.Out.WriteLine("Message: " + Msg);
				Console.Out.WriteLine("Signature: " + Signature);
				Console.Out.WriteLine("Salt: " + SaltVal);

				Assert.Fail(Pass ? "Should pass." : "Should fail");
			}
		}

		[TestMethod]
		[DataRow(
			typeof(Sha256),
			typeof(Sha256),
			"",
			"010001",
			"",
			"",
			32)]
		public void Test_02_VerifySignature(Type HashFunction, Type Mgf1HashFunction, string Modulus,
			string Exponent, string Msg, string Signature, int SaltLen)
		{
			this.Test_01_VerifySignature(HashFunction, Mgf1HashFunction, Modulus, Exponent, Msg, Signature,
				Hashes.BinaryToString(new byte[SaltLen]), true);
		}
	}
